#nullable enable

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace DTXMania.Game.Lib.Song
{
    /// <summary>
    /// Read-only songs shipped next to the executable (the metronome-only practice
    /// charts generated by tools/practicegen). The folder is scanned as one extra song
    /// root after the configured roots and merged into the top level of the library
    /// instead of getting its own root BOX. Scores live in songs.db, so nothing is
    /// ever written into it.
    /// </summary>
    internal static class BundledSongs
    {
        internal const string DirectoryName = "BundledSongs";

        /// <summary>
        /// Where this executable's bundled songs live, whether or not the folder exists.
        /// A macOS .app resolves to Contents/MacOS/BundledSongs, since the published
        /// output is copied there wholesale.
        /// </summary>
        internal static string Root { get; } =
            Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, DirectoryName));

        /// <summary>
        /// Returns <paramref name="configuredRoots"/> followed by
        /// <paramref name="bundledRoot"/> when that folder exists on disk.
        /// </summary>
        internal static string[] AppendTo(IEnumerable<string> configuredRoots, string? bundledRoot)
        {
            ArgumentNullException.ThrowIfNull(configuredRoots);

            var roots = configuredRoots.ToList();
            if (!string.IsNullOrWhiteSpace(bundledRoot) && Directory.Exists(bundledRoot))
                roots.Add(bundledRoot);

            return roots.ToArray();
        }
    }
}
